Index: src/frontend/src/components/flow/ConvertInquiryWizard.tsx
===================================================================
--- src/frontend/src/components/flow/ConvertInquiryWizard.tsx	
+++ src/frontend/src/components/flow/ConvertInquiryWizard.tsx	
@@ -0,0 +1,526 @@
+import { useState } from "react";
+import { useNavigate } from "react-router-dom";
+import { useQuery, useMutation } from "@tanstack/react-query";
+import { api } from "@/lib/api";
+import { getAccessToken } from "@/lib/auth";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Label } from "@/components/ui/label";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { ClientForm } from "@/components/clients/ClientForm";
+import {
+  Select,
+  SelectContent,
+  SelectItem,
+  SelectTrigger,
+  SelectValue,
+} from "@/components/ui/select";
+import { ArrowLeft, ArrowRight, Check, Search, Plus, Loader2 } from "lucide-react";
+import type { Client, Project } from "@/types/api";
+
+interface ConvertInquiryWizardProps {
+  inquiryId: string;
+  inquiryData: {
+    inquiry_id: string;
+    client_name: string;
+    estimated_value: number | null;
+    requirement_summary: string | null;
+  };
+}
+
+type WizardStep = "client" | "project" | "summary";
+
+interface ProjectData {
+  name: string;
+  code: string;
+  description: string;
+  location: string;
+  estimated_value: number | null;
+  start_date: string;
+  target_end_date: string;
+  pm_id: string;
+}
+
+export function ConvertInquiryWizard({ inquiryId, inquiryData }: ConvertInquiryWizardProps) {
+  const navigate = useNavigate();
+  const [step, setStep] = useState<WizardStep>("client");
+  const [clientMode, setClientMode] = useState<"search" | "create">("search");
+  const [searchQuery, setSearchQuery] = useState("");
+  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
+  const [newClientData, setNewClientData] = useState<Partial<Client> | null>(null);
+  const [projectData, setProjectData] = useState<ProjectData>({
+    name: `${inquiryData.client_name} - ${inquiryData.inquiry_id}`,
+    code: "",
+    description: inquiryData.requirement_summary || `Project created from inquiry ${inquiryData.inquiry_id}`,
+    location: "",
+    estimated_value: inquiryData.estimated_value,
+    start_date: new Date().toISOString().split("T")[0],
+    target_end_date: "",
+    pm_id: "",
+  });
+  const [error, setError] = useState<string | null>(null);
+
+  const { data: clientsData, isLoading: isLoadingClients } = useQuery({
+    queryKey: ["clients-search", searchQuery],
+    queryFn: () => api.listClients({ q: searchQuery, page_size: 50 }),
+    enabled: searchQuery.length > 0,
+  });
+
+  const { data: pmUsers } = useQuery({
+    queryKey: ["users-pm"],
+    queryFn: () => api.listUsers({ role: "pm" }),
+  });
+
+  const createClientMutation = useMutation({
+    mutationFn: (data: Partial<Client>) => api.createClient(data),
+  });
+
+  const createProjectMutation = useMutation({
+    mutationFn: (data: Partial<Project>) => api.createProject(data),
+  });
+
+  const transitionInquiryMutation = useMutation({
+    mutationFn: async (data: { status: string; client_code: string; client_primary_email: string; service_name: string; start_date: string }) => {
+      const token = getAccessToken();
+      const response = await fetch(`/api/inquiries/${inquiryId}/transition`, {
+        method: "POST",
+        headers: {
+          "Content-Type": "application/json",
+          ...(token ? { Authorization: `Bearer ${token}` } : {}),
+        },
+        body: JSON.stringify(data),
+      });
+      if (!response.ok) {
+        const error = await response.json().catch(() => ({ detail: "Unknown error" }));
+        throw new Error(error.detail || `HTTP ${response.status}`);
+      }
+      return response.json();
+    },
+  });
+
+  const handleClientSelect = (client: Client) => {
+    setSelectedClient(client);
+    setClientMode("search");
+    setSearchQuery("");
+  };
+
+  const handleClientCreate = async (data: Record<string, unknown>) => {
+    try {
+      setError(null);
+      const created = await createClientMutation.mutateAsync(data as Partial<Client>);
+      setSelectedClient(created);
+      setNewClientData(created);
+      setClientMode("search");
+      setStep("project");
+    } catch (err) {
+      setError(err instanceof Error ? err.message : "Failed to create client");
+    }
+  };
+
+  const handleProjectCreate = () => {
+    if (!projectData.name || !projectData.code) {
+      setError("Project name and code are required");
+      return;
+    }
+    if (!selectedClient) {
+      setError("Please select or create a client first");
+      return;
+    }
+    setError(null);
+    setStep("summary");
+  };
+
+  const handleSubmit = async () => {
+    if (!selectedClient) {
+      setError("No client selected");
+      return;
+    }
+
+    try {
+      setError(null);
+
+      const project = await createProjectMutation.mutateAsync({
+        client_id: selectedClient.id,
+        name: projectData.name,
+        code: projectData.code,
+        description: projectData.description || null,
+        location: projectData.location || null,
+        estimated_value: projectData.estimated_value,
+        start_date: projectData.start_date || null,
+        target_end_date: projectData.target_end_date || null,
+        pm_id: projectData.pm_id || null,
+        status: "Lead",
+      } as Partial<Project>);
+
+      const today = new Date().toISOString().split("T")[0];
+      await transitionInquiryMutation.mutateAsync({
+        status: "converted",
+        client_code: selectedClient.code,
+        client_primary_email: selectedClient.primary_email,
+        service_name: projectData.name,
+        start_date: projectData.start_date || today,
+      });
+
+      navigate(`/projects/${project.id}`, {
+        state: { convertedFromInquiry: inquiryId },
+      });
+    } catch (err) {
+      setError(err instanceof Error ? err.message : "Conversion failed");
+    }
+  };
+
+  const filteredClients = clientsData?.items || [];
+  const canProceedFromClient = selectedClient !== null;
+  const canProceedFromProject = projectData.name.length > 0 && projectData.code.length > 0;
+
+  return (
+    <div className="space-y-6">
+      <div className="flex items-center justify-between">
+        <div>
+          <h1 className="text-2xl font-bold">Convert Inquiry</h1>
+          <p className="text-muted-foreground">
+            Inquiry: {inquiryData.inquiry_id} — {inquiryData.client_name}
+          </p>
+        </div>
+        <Button variant="outline" onClick={() => navigate("/inquiries")}>
+          Cancel
+        </Button>
+      </div>
+
+      <div className="flex items-center gap-2 text-sm">
+        <div
+          className={`flex items-center gap-2 px-3 py-1 rounded-full ${
+            step === "client" ? "bg-primary text-primary-foreground" : "bg-muted"
+          }`}
+        >
+          {step === "client" ? <span className="font-bold">1</span> : <Check className="h-4 w-4" />}
+          <span>Client</span>
+        </div>
+        <div className="h-px flex-1 bg-border" />
+        <div
+          className={`flex items-center gap-2 px-3 py-1 rounded-full ${
+            step === "project" ? "bg-primary text-primary-foreground" : "bg-muted"
+          }`}
+        >
+          {step === "project" ? <span className="font-bold">2</span> : <Check className="h-4 w-4" />}
+          <span>Project</span>
+        </div>
+        <div className="h-px flex-1 bg-border" />
+        <div
+          className={`flex items-center gap-2 px-3 py-1 rounded-full ${
+            step === "summary" ? "bg-primary text-primary-foreground" : "bg-muted"
+          }`}
+        >
+          {step === "summary" ? <span className="font-bold">3</span> : <Check className="h-4 w-4" />}
+          <span>Summary</span>
+        </div>
+      </div>
+
+      {error && (
+        <div className="bg-destructive/10 border border-destructive text-destructive px-4 py-3 rounded-md">
+          {error}
+        </div>
+      )}
+
+      {step === "client" && (
+        <Card>
+          <CardHeader>
+            <CardTitle>Step 1: Select or Create Client</CardTitle>
+          </CardHeader>
+          <CardContent className="space-y-6">
+            <div className="flex gap-2">
+              <Button
+                variant={clientMode === "search" ? "default" : "outline"}
+                onClick={() => setClientMode("search")}
+              >
+                <Search className="mr-2 h-4 w-4" />
+                Search Existing
+              </Button>
+              <Button
+                variant={clientMode === "create" ? "default" : "outline"}
+                onClick={() => setClientMode("create")}
+              >
+                <Plus className="mr-2 h-4 w-4" />
+                Create New
+              </Button>
+            </div>
+
+            {clientMode === "search" && (
+              <div className="space-y-4">
+                <div className="space-y-2">
+                  <Label>Search Clients</Label>
+                  <Input
+                    placeholder="Search by name..."
+                    value={searchQuery}
+                    onChange={(e) => setSearchQuery(e.target.value)}
+                  />
+                </div>
+
+                {isLoadingClients && (
+                  <div className="flex items-center justify-center py-8">
+                    <Loader2 className="h-6 w-6 animate-spin" />
+                  </div>
+                )}
+
+                {searchQuery && !isLoadingClients && filteredClients.length === 0 && (
+                  <p className="text-muted-foreground text-center py-4">
+                    No clients found. Create a new one instead.
+                  </p>
+                )}
+
+                {filteredClients.length > 0 && (
+                  <div className="space-y-2">
+                    <Label>Select a Client</Label>
+                    <div className="border rounded-md divide-y">
+                      {filteredClients.map((client) => (
+                        <button
+                          key={client.id}
+                          type="button"
+                          className={`w-full text-left px-4 py-3 hover:bg-muted transition-colors ${
+                            selectedClient?.id === client.id ? "bg-primary/10" : ""
+                          }`}
+                          onClick={() => handleClientSelect(client)}
+                        >
+                          <div className="font-medium">{client.name}</div>
+                          <div className="text-sm text-muted-foreground">
+                            {client.code} — {client.primary_email}
+                          </div>
+                        </button>
+                      ))}
+                    </div>
+                  </div>
+                )}
+
+                {selectedClient && clientMode === "search" && (
+                  <div className="flex items-center gap-2 p-4 bg-green-50 border border-green-200 rounded-md">
+                    <Check className="h-5 w-5 text-green-600" />
+                    <span className="text-green-800">
+                      Selected: <strong>{selectedClient.name}</strong> ({selectedClient.code})
+                    </span>
+                  </div>
+                )}
+              </div>
+            )}
+
+            {clientMode === "create" && (
+              <ClientForm
+                initialData={{
+                  name: inquiryData.client_name,
+                  primary_email: "",
+                }}
+                onSubmit={handleClientCreate}
+                onCancel={() => setClientMode("search")}
+                isLoading={createClientMutation.isPending}
+              />
+            )}
+
+            <div className="flex justify-end">
+              <Button
+                onClick={() => setStep("project")}
+                disabled={!canProceedFromClient}
+              >
+                Next
+                <ArrowRight className="ml-2 h-4 w-4" />
+              </Button>
+            </div>
+          </CardContent>
+        </Card>
+      )}
+
+      {step === "project" && (
+        <Card>
+          <CardHeader>
+            <CardTitle>Step 2: Project Details</CardTitle>
+          </CardHeader>
+          <CardContent className="space-y-4">
+            <div className="grid grid-cols-2 gap-4">
+              <div className="space-y-2">
+                <Label>Project Name *</Label>
+                <Input
+                  value={projectData.name}
+                  onChange={(e) => setProjectData({ ...projectData, name: e.target.value })}
+                />
+              </div>
+              <div className="space-y-2">
+                <Label>Project Code *</Label>
+                <Input
+                  value={projectData.code}
+                  onChange={(e) => setProjectData({ ...projectData, code: e.target.value })}
+                  placeholder="SWA-2026-PRJ-001"
+                />
+              </div>
+            </div>
+
+            <div className="space-y-2">
+              <Label>Description</Label>
+              <Input
+                value={projectData.description}
+                onChange={(e) => setProjectData({ ...projectData, description: e.target.value })}
+              />
+            </div>
+
+            <div className="grid grid-cols-2 gap-4">
+              <div className="space-y-2">
+                <Label>Location</Label>
+                <Input
+                  value={projectData.location}
+                  onChange={(e) => setProjectData({ ...projectData, location: e.target.value })}
+                />
+              </div>
+              <div className="space-y-2">
+                <Label>Estimated Value (INR)</Label>
+                <Input
+                  type="number"
+                  value={projectData.estimated_value || ""}
+                  onChange={(e) =>
+                    setProjectData({
+                      ...projectData,
+                      estimated_value: e.target.value ? Number(e.target.value) : null,
+                    })
+                  }
+                />
+              </div>
+            </div>
+
+            <div className="grid grid-cols-2 gap-4">
+              <div className="space-y-2">
+                <Label>Start Date</Label>
+                <Input
+                  type="date"
+                  value={projectData.start_date}
+                  onChange={(e) => setProjectData({ ...projectData, start_date: e.target.value })}
+                />
+              </div>
+              <div className="space-y-2">
+                <Label>Target End Date</Label>
+                <Input
+                  type="date"
+                  value={projectData.target_end_date}
+                  onChange={(e) => setProjectData({ ...projectData, target_end_date: e.target.value })}
+                />
+              </div>
+            </div>
+
+            <div className="space-y-2">
+              <Label>Project Manager</Label>
+              <Select
+                onValueChange={(v) => setProjectData({ ...projectData, pm_id: v === "none" ? "" : v })}
+                value={projectData.pm_id || "none"}
+              >
+                <SelectTrigger>
+                  <SelectValue placeholder="Select PM" />
+                </SelectTrigger>
+                <SelectContent>
+                  <SelectItem value="none">None</SelectItem>
+                  {pmUsers?.items
+                    .filter((u) => u.role === "admin" || u.role === "pm")
+                    .map((u) => (
+                      <SelectItem key={u.id} value={u.id}>
+                        {u.name}
+                      </SelectItem>
+                    ))}
+                </SelectContent>
+              </Select>
+            </div>
+
+            <div className="flex justify-between">
+              <Button variant="outline" onClick={() => setStep("client")}>
+                <ArrowLeft className="mr-2 h-4 w-4" />
+                Back
+              </Button>
+              <Button onClick={handleProjectCreate} disabled={!canProceedFromProject}>
+                Next
+                <ArrowRight className="ml-2 h-4 w-4" />
+              </Button>
+            </div>
+          </CardContent>
+        </Card>
+      )}
+
+      {step === "summary" && (
+        <Card>
+          <CardHeader>
+            <CardTitle>Step 3: Review and Confirm</CardTitle>
+          </CardHeader>
+          <CardContent className="space-y-6">
+            <div className="space-y-4">
+              <div className="border rounded-lg p-4 space-y-2">
+                <h3 className="font-medium">Inquiry</h3>
+                <div className="text-sm text-muted-foreground">
+                  <p>
+                    <strong>{inquiryData.inquiry_id}</strong> — {inquiryData.client_name}
+                  </p>
+                  {inquiryData.requirement_summary && (
+                    <p className="mt-1">{inquiryData.requirement_summary}</p>
+                  )}
+                </div>
+              </div>
+
+              <div className="border rounded-lg p-4 space-y-2">
+                <h3 className="font-medium">Client</h3>
+                <div className="text-sm text-muted-foreground">
+                  <p>
+                    <strong>{selectedClient?.name}</strong> ({selectedClient?.code})
+                  </p>
+                  <p>{selectedClient?.primary_email}</p>
+                  {newClientData && (
+                    <p className="text-green-600 mt-1">Newly created</p>
+                  )}
+                </div>
+              </div>
+
+              <div className="border rounded-lg p-4 space-y-2">
+                <h3 className="font-medium">Project</h3>
+                <div className="text-sm text-muted-foreground">
+                  <p>
+                    <strong>{projectData.name}</strong> ({projectData.code})
+                  </p>
+                  {projectData.description && <p>{projectData.description}</p>}
+                  {projectData.location && (
+                    <p className="mt-1">Location: {projectData.location}</p>
+                  )}
+                  {projectData.estimated_value && (
+                    <p>Estimated Value: ₹{projectData.estimated_value.toLocaleString()}</p>
+                  )}
+                  {projectData.start_date && (
+                    <p>Start Date: {projectData.start_date}</p>
+                  )}
+                </div>
+              </div>
+            </div>
+
+            <div className="bg-muted/50 p-4 rounded-lg">
+              <p className="text-sm">
+                By clicking "Convert", the inquiry will be marked as converted and a new project will be created.
+                A service agreement will also be automatically created.
+              </p>
+            </div>
+
+            <div className="flex justify-between">
+              <Button variant="outline" onClick={() => setStep("project")}>
+                <ArrowLeft className="mr-2 h-4 w-4" />
+                Back
+              </Button>
+              <Button
+                onClick={handleSubmit}
+                disabled={createProjectMutation.isPending || transitionInquiryMutation.isPending}
+              >
+                {createProjectMutation.isPending || transitionInquiryMutation.isPending ? (
+                  <>
+                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
+                    Converting...
+                  </>
+                ) : (
+                  <>
+                    <Check className="mr-2 h-4 w-4" />
+                    Convert
+                  </>
+                )}
+              </Button>
+            </div>
+          </CardContent>
+        </Card>
+      )}
+    </div>
+  );
+}
