import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";

const projectSchema = z.object({
  name: z.string().min(1, "Name is required"),
  code: z.string().min(1, "Code is required"),
  client_id: z.string().min(1, "Client is required"),
  description: z.string().optional(),
  location: z.string().optional(),
  estimated_value: z.number().optional(),
  start_date: z.string().optional(),
  target_end_date: z.string().optional(),
  pm_id: z.string().optional(),
  designer_id: z.string().optional(),
  auditor_id: z.string().optional(),
});

type ProjectFormData = z.infer<typeof projectSchema>;

interface ProjectFormProps {
  initialData?: Partial<ProjectFormData>;
  onSubmit: (data: ProjectFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function ProjectForm({ initialData, onSubmit, onCancel, isLoading }: ProjectFormProps) {
  const form = useForm<ProjectFormData>({
    resolver: zodResolver(projectSchema),
    defaultValues: initialData,
  });

  const { data: clientsData } = useQuery({
    queryKey: ["clients-select"],
    queryFn: () => api.listClients({ page_size: 100 }),
  });

  const { data: pmUsers } = useQuery({
    queryKey: ["users-pm"],
    queryFn: () => api.listUsers({ role: "pm" }),
  });

  const { data: designerUsers } = useQuery({
    queryKey: ["users-designer"],
    queryFn: () => api.listUsers({ role: "designer" }),
  });

  const { data: auditorUsers } = useQuery({
    queryKey: ["users-auditor"],
    queryFn: () => api.listUsers({ role: "auditor" }),
  });

  const handleSubmit = async (data: ProjectFormData) => {
    await onSubmit(data);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Project Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="name">Name *</Label>
              <Input id="name" {...form.register("name")} />
              {form.formState.errors.name && (
                <p className="text-sm text-red-500">{form.formState.errors.name.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="code">Code *</Label>
              <Input id="code" {...form.register("code")} />
              {form.formState.errors.code && (
                <p className="text-sm text-red-500">{form.formState.errors.code.message as string}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="client_id">Client *</Label>
            <Select onValueChange={(v) => form.setValue("client_id", v)} defaultValue={initialData?.client_id}>
              <SelectTrigger>
                <SelectValue placeholder="Select a client" />
              </SelectTrigger>
              <SelectContent>
                {clientsData?.items.map((c) => (
                  <SelectItem key={c.id} value={c.id}>{c.name} ({c.code})</SelectItem>
                ))}
              </SelectContent>
            </Select>
            {form.formState.errors.client_id && (
              <p className="text-sm text-red-500">{form.formState.errors.client_id.message as string}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea id="description" {...form.register("description")} />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="location">Location</Label>
              <Input id="location" {...form.register("location")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="estimated_value">Estimated Value (INR)</Label>
              <Input id="estimated_value" type="number" {...form.register("estimated_value", { valueAsNumber: true })} />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="start_date">Start Date</Label>
              <Input id="start_date" type="date" {...form.register("start_date")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="target_end_date">Target End Date</Label>
              <Input id="target_end_date" type="date" {...form.register("target_end_date")} />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="pm_id">Project Manager</Label>
              <Select onValueChange={(v) => form.setValue("pm_id", v === "none" ? "" : v)} defaultValue={initialData?.pm_id || "none"}>
                <SelectTrigger>
                  <SelectValue placeholder="Select PM" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">None</SelectItem>
                  {pmUsers?.items.filter(u => u.role === "admin" || u.role === "pm").map((u) => (
                    <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="designer_id">Designer</Label>
              <Select onValueChange={(v) => form.setValue("designer_id", v === "none" ? "" : v)} defaultValue={initialData?.designer_id || "none"}>
                <SelectTrigger>
                  <SelectValue placeholder="Select Designer" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">None</SelectItem>
                  {designerUsers?.items.filter(u => u.role === "admin" || u.role === "designer").map((u) => (
                    <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="auditor_id">Auditor</Label>
              <Select onValueChange={(v) => form.setValue("auditor_id", v === "none" ? "" : v)} defaultValue={initialData?.auditor_id || "none"}>
                <SelectTrigger>
                  <SelectValue placeholder="Select Auditor" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">None</SelectItem>
                  {auditorUsers?.items.filter(u => u.role === "admin" || u.role === "auditor").map((u) => (
                    <SelectItem key={u.id} value={u.id}>{u.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="p-3 bg-muted rounded-md">
            <span className="font-medium">Status:</span> <span className="text-muted-foreground">Lead (default)</span>
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

from __future__ import annotations

import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.inquiry import InquiryStatus
from src.backend.models.user import User
from src.backend.schemas.inquiry import (
    InquiryCreate,
    InquiryListResponse,
    InquiryRead,
    InquiryUpdate,
)
from src.backend.services import inquiry_service
from src.backend.services.inquiry_service import InquiryAlreadyConvertedError

router = APIRouter(prefix="/api/inquiries", tags=["inquiries"])


@router.get("", response_model=InquiryListResponse)
def list_inquiries(
    _: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
    q: str | None = None,
    status_filter: str | None = Query(default=None, alias="status"),
) -> InquiryListResponse:
    items, total, page, page_size = inquiry_service.list_inquiries_service(
        db, page=page, page_size=page_size, q=q, status=status_filter
    )
    return InquiryListResponse(
        items=[InquiryRead.model_validate(i) for i in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("", response_model=InquiryRead, status_code=status.HTTP_201_CREATED)
def create_inquiry(
    body: InquiryCreate,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InquiryRead:
    inquiry = inquiry_service.create_inquiry_service(db, body, current_user.id)
    return InquiryRead.model_validate(inquiry)


@router.get("/{inquiry_id}", response_model=InquiryRead)
def get_inquiry(
    inquiry_id: uuid.UUID,
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InquiryRead:
    inquiry = inquiry_service.get_inquiry_service(db, inquiry_id)
    if not inquiry:
        raise HTTPException(status_code=404, detail="Inquiry not found")
    return InquiryRead.model_validate(inquiry)


@router.patch("/{inquiry_id}", response_model=InquiryRead)
def update_inquiry(
    inquiry_id: uuid.UUID,
    body: InquiryUpdate,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InquiryRead:
    inquiry = inquiry_service.update_inquiry_service(db, inquiry_id, body, current_user.id)
    if not inquiry:
        raise HTTPException(status_code=404, detail="Inquiry not found")
    return InquiryRead.model_validate(inquiry)


@router.delete("/{inquiry_id}", status_code=status.HTTP_204_NO_CONTENT, response_class=Response)
def delete_inquiry(
    inquiry_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
):
    ok = inquiry_service.delete_inquiry_service(db, inquiry_id, current_user.id)
    if not ok:
        raise HTTPException(status_code=404, detail="Inquiry not found")
    return Response(status_code=status.HTTP_204_NO_CONTENT)


class TransitionRequestBody(dict):
    pass


@router.post("/{inquiry_id}/transition", response_model=InquiryRead)
def transition_inquiry(
    inquiry_id: uuid.UUID,
    body: dict,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> InquiryRead:
    new_status_str = body.get("status")
    if not new_status_str:
        raise HTTPException(status_code=422, detail="status is required")
    try:
        new_status = InquiryStatus(new_status_str)
    except ValueError as e:
        raise HTTPException(status_code=422, detail=f"invalid status: {new_status_str}") from e

    try:
        inquiry, agreement = inquiry_service.transition_inquiry_service(
            db,
            inquiry_id,
            new_status,
            current_user.id,
            client_code=body.get("client_code"),
            client_primary_email=body.get("client_primary_email"),
            service_name=body.get("service_name"),
            start_date=body.get("start_date") or None,
        )
    except LookupError as e:
        raise HTTPException(status_code=404, detail=str(e)) from e
    except InquiryAlreadyConvertedError as e:
        raise HTTPException(status_code=409, detail=str(e)) from e
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e)) from e

    _ = agreement  # unused — handled inside service for completeness
    return InquiryRead.model_validate(inquiry)

