import { useParams, useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { ArrowLeft, Loader2 } from "lucide-react";
import { ConvertInquiryWizard } from "@/components/flow/ConvertInquiryWizard";

export function ConvertInquiryPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const { data: inquiry, isLoading, error } = useQuery({
    queryKey: ["inquiry", id],
    queryFn: () => api.getInquiry(id!),
    enabled: !!id,
  });

  if (!id) {
    return (
      <div className="space-y-4">
        <Button variant="ghost" asChild>
          <a href="/inquiries">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Inquiries
          </a>
        </Button>
        <p className="text-destructive">Inquiry ID is required</p>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  if (error || !inquiry) {
    return (
      <div className="space-y-4">
        <Button variant="ghost" asChild>
          <a href="/inquiries">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Inquiries
          </a>
        </Button>
        <Card>
          <CardContent className="pt-6">
            <p className="text-destructive">
              Failed to load inquiry: {error instanceof Error ? error.message : "Unknown error"}
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (inquiry.status === "converted") {
    return (
      <div className="space-y-4">
        <Button variant="ghost" asChild>
          <a href="/inquiries">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Inquiries
          </a>
        </Button>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              This inquiry has already been converted.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <Button variant="ghost" asChild>
        <a href="/inquiries">
          <ArrowLeft className="mr-2 h-4 w-4" />
          Back to Inquiries
        </a>
      </Button>

      <ConvertInquiryWizard
        inquiryId={inquiry.id}
        inquiryData={{
          inquiry_id: inquiry.inquiry_id,
          client_name: inquiry.client_name,
          estimated_value: inquiry.estimated_value,
          requirement_summary: inquiry.requirement_summary,
        }}
      />
    </div>
  );
}

